24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  // One answer chain per socket: a frame answered beside the turn still owes its socket the arrival order.
37	  const answered = new WeakMap<WebSocket, Promise<void>>();
38	  return function handleMessage(
39	    ws: WebSocket,
40	    session: ChatSession,
41	    rawMessage: unknown,
42	    signal?: AbortSignal
43	  ): Promise<void> {
44	    const validation = validateMessage(rawMessage);
45	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
46	    if (isUserMessageFrame(rawMessage)) {
47	      return lock.run(session.sessionId, () =>
48	        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
49	      );
50	    }
51	    return answerBesideTheTurn(ws, session, validation, sessionStore, answered);
52	  };
53	}
54	
55	// Answered once the answers this socket is already owed have gone out: a frame sent after a list
56	// must not see its pong overtake that list. It never waits on the lock, so it still answers mid-turn.
57	function answerBesideTheTurn(
58	  ws: WebSocket,
59	  session: ChatSession,
60	  validation: ValidationResult,
61	  sessionStore: SessionStore | undefined,
62	  answered: WeakMap<WebSocket, Promise<void>>
63	): Promise<void> {
64	  const owed = answered.get(ws) ?? Promise.resolve();
65	  const answer = owed.then(() => wsErrorHandler(ws, () => answerFrame(ws, session, validation, sessionStore)));
66	  // The tail never rejects: the next frame chains on it, and the connection dispatches without awaiting.
67	  answered.set(
68	    ws,
69	    answer.catch(() => undefined)
70	  );
71	  return answer;
72	}
73	
74	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
75	async function answerInTurn(
76	  ws: WebSocket,
77	  session: ChatSession,
78	  orchestrator: ChatOrchestrator,
79	  validation: ValidationResult,
80	  signal: AbortSignal | undefined,
81	  sessionStore: SessionStore | undefined
82	): Promise<void> {
83	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
84	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
85	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
86	    return;
87	  }
88	  const startedAt = Date.now();
89	  try {
90	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore));
91	  } finally {
92	    endTurn(ws, session, signal, startedAt);
93	  }
94	}
95	
96	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
97	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
98	  if (signal?.aborted) {
99	    log.info('message', 'turn abandoned: its socket closed', {
100	      sessionId: session.sessionId,
101	      elapsedMs: Date.now() - startedAt,
102	    });
103	    return;
104	  }
105	  sendStreamEnd(ws);
106	}
107	
108	async function answerUserMessage(
109	  ws: WebSocket,
110	  session: ChatSession,
111	  orchestrator: ChatOrchestrator,
112	  validation: ValidationResult,
113	  signal: AbortSignal | undefined,
114	  sessionStore: SessionStore | undefined
115	): Promise<void> {
116	  const message = validation.valid ? validation.data : undefined;
117	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
118	  await answerFrame(ws, session, validation, sessionStore);
119	}
120	
121	async function answerFrame(
122	  ws: WebSocket,
123	  session: ChatSession,
124	  validation: ValidationResult,
125	  sessionStore: SessionStore | undefined
126	): Promise<void> {
127	  if (!validation.valid) {
128	    log.warn('message', 'validation failed', {error: validation.error});
129	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
130	    return;
131	  }
132	
133	  const message = validation.data;
134	  if (message.type === 'ping') handlePing(ws, message.timestamp);
135	  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
136	}
137	
138	// Read beside the lock: a history request is not a turn and must not queue behind a streaming answer.
139	async function handleListSessions(
140	  ws: WebSocket,
141	  session: ChatSession,
142	  sessionStore: SessionStore | undefined,
143	  message: ListSessionsMessage
144	): Promise<void> {
145	  try {
146	    const summaries =
147	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
148	    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
149	  } catch (error) {
150	    // No store detail reaches the frame or the log beyond the message: both leave the process.
151	    const detail = error instanceof Error ? error.message : 'Unknown error';
152	    log.error('ws', 'listing conversations failed', {
153	      sessionId: session.sessionId,
154	      userId: session.userId,
155	      error: detail,
156	    });
157	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
158	  }
159	}
160	
161	// A store may hand back a summary that went through JSON, so any shape a Date reads is serialised.
162	function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
163	  return {
164	    sessionId: summary.sessionId,
165	    createdAt: toIso(summary.createdAt),
166	    updatedAt: toIso(summary.updatedAt),
167	    entryCount: summary.entryCount,
168	  };
169	}
170	
171	function toIso(value: Date): string {
172	  return new Date(value).toISOString();
173	}
174	
175	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
176	function isUserMessageFrame(rawMessage: unknown): boolean {
177	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
178	}
179	
180	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
181	  try {
182	    await action();
183	  } catch (error) {
184	    const message = error instanceof Error ? error.message : 'Unknown error';
185	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
186	    log.error('message', 'handling error', {error: message, code});
187	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
188	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
189	      return;
190	    }
191	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
192	  }
193	}
194	
195	async function handleUserMessage(
196	  ws: WebSocket,
197	  session: ChatSession,
198	  orchestrator: ChatOrchestrator,
199	  content: string,
200	  signal: AbortSignal | undefined
201	): Promise<void> {
202	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
203	
204	  const userEntry = createUserEntry(content);
205	  const userIndex = appendEntry(session, userEntry);
206	  sendUpsert(ws, userIndex, userEntry);
207	
208	  const parser = new ThinkingTagParser();
209	  const state: StreamState = {
210	    thinkingIndex: null,
211	    assistantIndex: null,
212	    suppressOutput: false,
213	    sentAssistantIndices: [],
214	  };
215	
216	  let textChunkCount = 0;
217	
218	  try {
219	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
220	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
221	      if (signal?.aborted) break;
222	      textChunkCount = logChunk(chunk, textChunkCount);
223	      processChunk(ws, session, state, parser, chunk);
224	    }
225	  } finally {
226	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
227	    flushHeldText(ws, session, state, parser);
228	    closeCutOff(ws, session, state, 'thinkingIndex');
229	    closeCutOff(ws, session, state, 'assistantIndex');
230	  }
231	
232	  if (textChunkCount > 0) {
233	    log.debug('stream', `received ${textChunkCount} text chunks`);
234	  }
235	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
236	}
237	
238	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
239	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
240	  if (chunk.type === 'text') return textChunkCount + 1;
241	
242	  if (textChunkCount > 0) {
243	    log.debug('stream', `received ${textChunkCount} text chunks`);
244	  }
245	
246	  if (chunk.type === 'tool_result') {
247	    log.debug('stream', 'tool_result chunk', {
248	      messageCount: chunk.clientMessages.length,
249	      types: chunk.clientMessages.map(m => m.type),
250	    });
251	    return 0;
252	  }
253	
254	  log.debug('stream', 'chunk', {type: chunk.type});
255	  return 0;
256	}
257	
258	function processChunk(
259	  ws: WebSocket,
260	  session: ChatSession,
261	  state: StreamState,
262	  parser: ThinkingTagParser,
263	  chunk: MessageChunk
264	): void {
265	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
266	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
267	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
268	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
269	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
270	}
271	
272	function processTextChunk(
273	  ws: WebSocket,
274	  session: ChatSession,
275	  state: StreamState,
276	  parser: ThinkingTagParser,
277	  text: string
278	): void {
279	  const segments = parser.push(text);
280	  for (const segment of segments) {
281	    handleTextSegment(ws, session, state, segment);
282	  }
283	}
284	
285	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
286	  if (segment.type === 'thinking') {
287	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
288	    return;
289	  }
290	  commitAndClear(ws, session, state, 'thinkingIndex');
291	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
292	}
293	
294	function streamSegment(
295	  ws: WebSocket,
296	  session: ChatSession,
297	  state: StreamState,
298	  key: StateIndexKey,
299	  createEntry: EntryFactory,
300	  content: string
301	): void {
302	  const isNew = initSegment(session, state, key, createEntry);
303	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
304	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
305	  appendDelta(session, state[key]!, content);
306	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
307	}
308	
309	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
310	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
311	  markSuppressed(session, index);
312	  sendSkip(ws, index);
313	}
314	
315	function markSuppressed(session: ChatSession, index: number): void {
316	  const entry = session.entries[index];
317	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
318	}
319	
320	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
321	  if (state[key] !== null) return false;
322	  state[key] = appendEntry(session, createEntry());
323	  return true;
324	}
325	
326	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
327	  const index = state[key];
328	  if (index === null) return;
329	
330	  commitEntry(session, index);
331	  state[key] = null;
332	
333	  // Only what the client received can be retracted, and only assistant entries.
334	  if (state.suppressOutput) return;
335	
336	  sendCommit(ws, index);
337	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
338	}
339	
340	function processToolUseChunk(
341	  ws: WebSocket,
342	  session: ChatSession,
343	  toolCall: {name: string; input: Record<string, unknown>}
344	): void {
345	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
346	  const toolIndex = appendEntry(session, toolEntry);
347	  sendUpsert(ws, toolIndex, toolEntry);
348	}
349	
350	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
351	  for (const msg of clientMessages) {
352	    log.debug('stream', 'forwarding client message to frontend', {
353	      type: msg.type,
354	      index: 'index' in msg ? msg.index : undefined,
355	    });
356	    sendJson(ws, msg);
357	  }
358	}
359	
360	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
361	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
362	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
363	  commitOpenEntries(ws, session, state);
364	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
365	
366	  for (const idx of state.sentAssistantIndices) {
367	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
368	    markSuppressed(session, idx);
369	  }
370	
371	  state.sentAssistantIndices = [];
372	  state.suppressOutput = true;
373	}
374	
375	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
376	  flushHeldText(ws, session, state, parser);
377	  commitOpenEntries(ws, session, state);
378	}
379	
380	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
381	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
382	  for (const segment of parser.flush()) {
383	    handleTextSegment(ws, session, state, segment);
384	  }
385	}
386	
387	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
388	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
389	  const index = state[key];
390	  if (index === null) return;
391	  markTruncated(session, index);
392	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
393	  commitAndClear(ws, session, state, key);
394	}
395	
396	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
397	  commitAndClear(ws, session, state, 'thinkingIndex');
398	  commitAndClear(ws, session, state, 'assistantIndex');
399	}
400	
401	function handlePing(ws: WebSocket, timestamp: number): void {
402	  sendJson(ws, {type: 'pong', timestamp});
403	}
